const memorySpiritSheet=new Image();memorySpiritSheet.assetSrc='assets/memory-spirit-v2.png';
function memorySpiritSample(a,point){return {x:point.x,y:point.y,valid:dist(a.origin,point)<=450&&lineClear(a.origin,point),fired:false};}
function beginMemorySpirit(e){e.state='attack';e.elapsed=0;e.struck=false;let a={pattern:'memoryReverseEcho',bespoke:true,windup:2,origin:{x:e.x,y:e.y},previous:{x:p.x,y:p.y},samples:[]};a.samples.push(memorySpiritSample(a,p));e.attack=a;}
const memorySpiritAnimateBase=animateEnemy;animateEnemy=(e,dt)=>{
 if(e.species!=='r9e7')return memorySpiritAnimateBase(e,dt);if(e.hp<=0||e.reactionStun>0||paused||dead||!Number.isFinite(dt)||dt<=0)return;e.anim+=dt;e.flash=Math.max(0,(e.flash||0)-dt);e.slow=Math.max(0,(e.slow||0)-dt);let a=e.attack;
 if(a?.pattern!=='memoryReverseEcho'){e.t-=dt;e.nav=(e.nav||0)-dt;let d=dist(e,p),clear=lineClear(e,p);if(e.t<=0&&d<=350&&clear){beginMemorySpirit(e);return;}e.state='idle';if(d>800&&!e.aware)return;if(e.nav<=0){e.nav=.8;e.path=clear?[{x:p.x,y:p.y}]:findPath(e,p);}let to=e.path?.[0];if(to){let dx=to.x-e.x,dy=to.y-e.y,len=Math.hypot(dx,dy);if(len<10)e.path.shift();else{let step=Math.min(len,68*(e.slow>0?.35:1)*dt);e.state=moveActor(e,dx/len*step,dy/len*step,18)>.1?'walk':'idle';e.facing=dx-dy<0?-1:1;}}return;}
 if(dist(e,a.origin)>24){e.attack=null;e.state='idle';e.t=1.5;return;}let before=e.elapsed;e.elapsed=Math.round((e.elapsed+dt)*1e6)/1e6;
 while(a.samples.length<3&&e.elapsed>=a.samples.length*.5){let at=a.samples.length*.5,t=Math.max(0,Math.min(1,(at-before)/(e.elapsed-before||1))),point={x:a.previous.x+(p.x-a.previous.x)*t,y:a.previous.y+(p.y-a.previous.y)*t};a.samples.push(memorySpiritSample(a,point));}a.previous={x:p.x,y:p.y};
 for(let i=2;i>=0&&!dead;i--){let sample=a.samples[i],at=3-i*.5;if(sample&&!sample.fired&&e.elapsed>=at){sample.fired=true;e.struck=true;if(sample.valid){if(dist(sample,p)<=65&&lineClear(a.origin,sample)&&lineClear(sample,p))hurt(56);playSound('impact',sample.x,sample.y);}}}
 if(e.elapsed>=4){e.attack=null;e.state='idle';e.t=3.2;}
};
const memorySpiritDrawBase=drawRegionEnemy;drawRegionEnemy=(e,size)=>{if(e.species!=='r9e7'||!memorySpiritSheet.complete||!memorySpiritSheet.naturalWidth||!memorySpiritSheet.naturalHeight)return memorySpiritDrawBase(e,size);let f=spriteFrame(e.state,e.anim||0);if(e.hp<=0)f={row:2,col:3};else if(e.attack?.pattern==='memoryReverseEcho')f={row:2,col:e.elapsed<1?0:e.elapsed<2?1:e.elapsed<3.2?2:3};let q=project(e.x,e.y),sw=memorySpiritSheet.naturalWidth/4,sh=memorySpiritSheet.naturalHeight/3,w=240,h=w*sh/sw,anchor=[[.92,.92,.91,.91],[.87,.82,.83,.87],[.85,.84,.84,.84]][f.row][f.col];ctx.save();ctx.translate(q.x,q.y-10-Math.sin((e.anim||0)*2)*3);ctx.scale(e.facing||1,1);ctx.filter=e.flash>0?'brightness(1.8)':'none';if(typeof drawPreparedEnemySprite==='function')drawPreparedEnemySprite(ctx,memorySpiritSheet,f.col*sw,f.row*sh,sw,sh,-w/2,-h*anchor,w,h);else ctx.drawImage(memorySpiritSheet,f.col*sw,f.row*sh,sw,sh,-w/2,-h*anchor,w,h);ctx.restore();return true;};
const memorySpiritSizeBase=enemyVisualSize;enemyVisualSize=e=>e.species==='r9e7'?175:memorySpiritSizeBase(e);
const memorySpiritGroundBase=drawGroundEffects;drawGroundEffects=()=>{memorySpiritGroundBase();for(let e of (typeof enemyRenderList==='function'?enemyRenderList('r9e7'):enemies)){let a=e.attack;if(e.species!=='r9e7'||e.hp<=0||a?.pattern!=='memoryReverseEcho')continue;for(let i=0;i<a.samples.length;i++){let sample=a.samples[i],at=3-i*.5;if(!sample.valid||!visibleAt(sample.x,sample.y)||e.elapsed>at+.25)continue;let remaining=at-e.elapsed,color=remaining<=0?'#d9fbff':remaining<.6?'#f3d28d':'#8bd9e0';groundRing(sample.x,sample.y,65,color,remaining<.6?3:1);groundRing(sample.x,sample.y,Math.max(0,Math.min(65,65*remaining)),color,1);let q=project(sample.x,sample.y);ctx.save();ctx.strokeStyle=color;ctx.lineWidth=2;for(let n=0;n<3-i;n++){ctx.beginPath();ctx.moveTo(q.x-8+(n-(2-i)/2)*9,q.y);ctx.lineTo(q.x-4+(n-(2-i)/2)*9,q.y-5);ctx.lineTo(q.x+(n-(2-i)/2)*9,q.y);ctx.stroke();}ctx.restore();}}};

if(typeof registerDirectEnemy==='function')registerDirectEnemy('r9e7',animateEnemy,drawRegionEnemy);
